package store

import (
	"encoding/json"
	"sort"
	"strings"
	"time"
)

// ---- plans

// CreatePlan adds a plan. UsageType defaults to Licensed; a new plan is active.
func (s *Store) CreatePlan(p Plan, now time.Time) (Plan, error) {
	p.Name = strings.TrimSpace(p.Name)
	if p.UsageType == "" {
		p.UsageType = Licensed
	}
	p.Active = true
	if err := checkPlan(p); err != nil {
		return Plan{}, err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.orgs[p.OrgID]; !ok {
		return Plan{}, ErrNotFound
	}
	p.ID = s.newID("plan")
	p.CreatedAt = now.UTC()
	s.plans[p.ID] = p
	return p, nil
}

func checkPlan(p Plan) error {
	switch {
	case p.Name == "":
		return invalid("a plan needs a name")
	case !p.Currency.Valid():
		return invalid("unknown currency %q", p.Currency)
	case p.UnitAmount < 0:
		return invalid("a plan's price cannot be negative")
	case p.Interval != Monthly && p.Interval != Yearly:
		return invalid("a plan bills every month or every year")
	case p.UsageType != Licensed && p.UsageType != Metered:
		return invalid("a plan is licensed or metered")
	case p.TrialDays < 0 || p.TrialDays > 365:
		return invalid("a trial lasts 0 to 365 days")
	}
	return nil
}

// Plan returns one of an organization's plans.
func (s *Store) Plan(orgID, id string) (Plan, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	p, ok := s.plans[id]
	if !ok || p.OrgID != orgID {
		return Plan{}, false
	}
	return p, true
}

// Plans returns an organization's plans, oldest first.
func (s *Store) Plans(orgID string) []Plan {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Plan{}
	for _, p := range s.plans {
		if p.OrgID == orgID {
			out = append(out, p)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// UpdatePlan changes a plan with f. Its currency, price, interval and usage type cannot change once created: subscriptions
// depend on them.
func (s *Store) UpdatePlan(orgID, id string, f func(*Plan) error) (Plan, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	old, ok := s.plans[id]
	if !ok || old.OrgID != orgID {
		return Plan{}, ErrNotFound
	}
	p := old
	if err := f(&p); err != nil {
		return Plan{}, err
	}
	p.ID, p.OrgID, p.CreatedAt = old.ID, old.OrgID, old.CreatedAt
	p.Currency, p.UnitAmount, p.Interval, p.UsageType = old.Currency, old.UnitAmount, old.Interval, old.UsageType
	p.Name = strings.TrimSpace(p.Name)
	if err := checkPlan(p); err != nil {
		return Plan{}, err
	}
	s.plans[id] = p
	return p, nil
}

// ---- subscriptions

// CreateSubscription stores a new subscription. The caller sets its status and periods.
func (s *Store) CreateSubscription(sub Subscription, now time.Time) (Subscription, error) {
	if sub.Quantity <= 0 {
		return Subscription{}, invalid("the quantity must be at least 1")
	}
	if sub.DiscountPercent < 0 || sub.DiscountPercent > 100 {
		return Subscription{}, invalid("the discount is 0 to 100 percent")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.customers[sub.CustomerID]; !ok {
		return Subscription{}, ErrNotFound
	}
	if p, ok := s.plans[sub.PlanID]; !ok || p.OrgID != sub.OrgID {
		return Subscription{}, ErrNotFound
	}
	sub.ID = s.newID("sub")
	sub.CreatedAt = now.UTC()
	s.subs[sub.ID] = sub
	return copySub(sub), nil
}

// Subscription returns one of an organization's subscriptions.
func (s *Store) Subscription(orgID, id string) (Subscription, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	sub, ok := s.subs[id]
	if !ok || sub.OrgID != orgID {
		return Subscription{}, false
	}
	return copySub(sub), true
}

// SubscriptionFilter narrows Subscriptions.
type SubscriptionFilter struct {
	CustomerID string
	Status     SubStatus
}

// Subscriptions returns an organization's subscriptions that match f, oldest first.
func (s *Store) Subscriptions(orgID string, f SubscriptionFilter) []Subscription {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Subscription{}
	for _, sub := range s.subs {
		if sub.OrgID != orgID || (f.CustomerID != "" && sub.CustomerID != f.CustomerID) || (f.Status != "" && sub.Status != f.Status) {
			continue
		}
		out = append(out, copySub(sub))
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// UpdateSubscription changes a subscription with f, which may refuse with an error.
func (s *Store) UpdateSubscription(orgID, id string, f func(*Subscription) error) (Subscription, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	old, ok := s.subs[id]
	if !ok || old.OrgID != orgID {
		return Subscription{}, ErrNotFound
	}
	sub := copySub(old)
	if err := f(&sub); err != nil {
		return Subscription{}, err
	}
	sub.ID, sub.OrgID, sub.CustomerID, sub.CreatedAt = old.ID, old.OrgID, old.CustomerID, old.CreatedAt
	if sub.Quantity <= 0 {
		return Subscription{}, invalid("the quantity must be at least 1")
	}
	if p, ok := s.plans[sub.PlanID]; !ok || p.OrgID != orgID {
		return Subscription{}, ErrNotFound
	}
	s.subs[id] = sub
	return copySub(sub), nil
}

// DueSubscriptions returns the subscriptions of every organization whose current period has ended by now and that are not
// canceled, the longest overdue first.
func (s *Store) DueSubscriptions(now time.Time) []Subscription {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Subscription{}
	for _, sub := range s.subs {
		if sub.Status != Canceled && !sub.CurrentPeriodEnd.After(now) {
			out = append(out, copySub(sub))
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].CurrentPeriodEnd.Equal(out[j].CurrentPeriodEnd) {
			return out[i].CurrentPeriodEnd.Before(out[j].CurrentPeriodEnd)
		}
		return out[i].ID < out[j].ID
	})
	return out
}

func copySub(sub Subscription) Subscription {
	if sub.TrialEnd != nil {
		t := *sub.TrialEnd
		sub.TrialEnd = &t
	}
	if sub.CanceledAt != nil {
		t := *sub.CanceledAt
		sub.CanceledAt = &t
	}
	return sub
}

// AddUsage records usage of a subscription to a metered plan at time at.
func (s *Store) AddUsage(orgID, subID string, quantity int64, at, now time.Time) (UsageRecord, error) {
	if quantity <= 0 {
		return UsageRecord{}, invalid("usage must be a positive quantity")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	sub, ok := s.subs[subID]
	if !ok || sub.OrgID != orgID {
		return UsageRecord{}, ErrNotFound
	}
	if p := s.plans[sub.PlanID]; p.UsageType != Metered {
		return UsageRecord{}, invalid("the subscription's plan is not metered")
	}
	u := UsageRecord{ID: s.newID("use"), OrgID: orgID, SubscriptionID: subID, Quantity: quantity, At: at.UTC(), CreatedAt: now.UTC()}
	s.usage = append(s.usage, u)
	return u, nil
}

// UsageTotal adds up a subscription's usage at times in [from, to).
func (s *Store) UsageTotal(orgID, subID string, from, to time.Time) int64 {
	s.mu.Lock()
	defer s.mu.Unlock()
	var n int64
	for _, u := range s.usage {
		if u.OrgID == orgID && u.SubscriptionID == subID && !u.At.Before(from) && u.At.Before(to) {
			n += u.Quantity
		}
	}
	return n
}

// ---- invoices

// CreateInvoice stores an invoice for one of the organization's customers, with the organization's tax rate. It is open.
func (s *Store) CreateInvoice(inv Invoice, now time.Time) (Invoice, error) {
	if !inv.Currency.Valid() {
		return Invoice{}, invalid("unknown currency %q", inv.Currency)
	}
	if inv.DiscountPercent < 0 || inv.DiscountPercent > 100 {
		return Invoice{}, invalid("the discount is 0 to 100 percent")
	}
	for _, l := range inv.Lines {
		if l.Quantity <= 0 {
			return Invoice{}, invalid("a line needs a positive quantity")
		}
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	org, ok := s.orgs[inv.OrgID]
	if !ok {
		return Invoice{}, ErrNotFound
	}
	c, ok := s.customers[inv.CustomerID]
	if !ok {
		return Invoice{}, ErrNotFound
	}
	if c.OrgID != inv.OrgID {
		return Invoice{}, ErrCustomerOrgMismatch
	}
	inv.ID = s.newID("in")
	inv.TaxRateBP = org.TaxRateBP
	inv.Status = InvoiceOpen
	inv.CreatedAt = now.UTC()
	inv.PaidAt, inv.VoidedAt = nil, nil
	inv = copyInvoice(inv)
	s.invoices[inv.ID] = inv
	return copyInvoice(inv), nil
}

// Invoice returns one of an organization's invoices.
func (s *Store) Invoice(orgID, id string) (Invoice, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	inv, ok := s.invoices[id]
	if !ok || inv.OrgID != orgID {
		return Invoice{}, false
	}
	return copyInvoice(inv), true
}

// InvoiceByID returns an invoice of any organization (background jobs and the admin tool).
func (s *Store) InvoiceByID(id string) (Invoice, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	inv, ok := s.invoices[id]
	return copyInvoice(inv), ok
}

// InvoiceFilter narrows ListInvoices.
type InvoiceFilter struct {
	CustomerID     string
	SubscriptionID string
	Status         InvoiceStatus
}

// ListInvoices returns an organization's invoices that match f, oldest first (ties by ID).
func (s *Store) ListInvoices(orgID string, f InvoiceFilter) []Invoice {
	s.mu.Lock()
	all := make([]Invoice, 0, len(s.invoices))
	for _, inv := range s.invoices {
		all = append(all, inv)
	}
	s.mu.Unlock()
	out := []Invoice{}
	for _, inv := range all {
		c := cloneInvoice(inv)
		if c.OrgID != orgID {
			continue
		}
		if (f.CustomerID != "" && c.CustomerID != f.CustomerID) || (f.SubscriptionID != "" && c.SubscriptionID != f.SubscriptionID) || (f.Status != "" && c.Status != f.Status) {
			continue
		}
		out = append(out, c)
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
			return out[i].CreatedAt.Before(out[j].CreatedAt)
		}
		return out[i].ID < out[j].ID
	})
	return out
}

// UpdateInvoice changes an invoice with f, which may refuse with an error. Only its status, timestamps and lines change.
func (s *Store) UpdateInvoice(orgID, id string, f func(*Invoice) error) (Invoice, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	old, ok := s.invoices[id]
	if !ok || old.OrgID != orgID {
		return Invoice{}, ErrNotFound
	}
	inv := copyInvoice(old)
	if err := f(&inv); err != nil {
		return Invoice{}, err
	}
	inv.ID, inv.OrgID, inv.CustomerID, inv.SubscriptionID, inv.Currency, inv.CreatedAt = old.ID, old.OrgID, old.CustomerID, old.SubscriptionID, old.Currency, old.CreatedAt
	s.invoices[id] = copyInvoice(inv)
	return copyInvoice(inv), nil
}

// copyInvoice is a deep copy, so callers cannot change stored lines.
func copyInvoice(inv Invoice) Invoice {
	inv.Lines = append([]Line(nil), inv.Lines...)
	for _, p := range []**time.Time{&inv.PeriodStart, &inv.PeriodEnd, &inv.PaidAt, &inv.VoidedAt} {
		if *p != nil {
			t := **p
			*p = &t
		}
	}
	return inv
}

// cloneInvoice is a deep copy through JSON, which cannot miss a field added later.
func cloneInvoice(inv Invoice) Invoice {
	b, err := json.Marshal(inv)
	if err != nil {
		return copyInvoice(inv)
	}
	var out Invoice
	if err := json.Unmarshal(b, &out); err != nil {
		return copyInvoice(inv)
	}
	return out
}

// ---- payments

// CreatePayment records a payment attempt for one of the organization's invoices.
func (s *Store) CreatePayment(p Payment, now time.Time) (Payment, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	inv, ok := s.invoices[p.InvoiceID]
	if !ok || inv.OrgID != p.OrgID {
		return Payment{}, ErrNotFound
	}
	if p.Status != PaymentSucceeded && p.Status != PaymentFailed {
		return Payment{}, invalid("a payment succeeded or failed")
	}
	p.ID = s.newID("pay")
	p.CreatedAt = now.UTC()
	s.payments[p.ID] = p
	return p, nil
}

// Payments returns an organization's payments, oldest first, only those of one invoice when invoiceID is set.
func (s *Store) Payments(orgID, invoiceID string) []Payment {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Payment{}
	for _, p := range s.payments {
		if p.OrgID == orgID && (invoiceID == "" || p.InvoiceID == invoiceID) {
			out = append(out, p)
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
			return out[i].CreatedAt.Before(out[j].CreatedAt)
		}
		return out[i].ID < out[j].ID
	})
	return out
}
package store

import (
	"fmt"
	"sort"
)

// State is everything a store holds, for snapshots (package snapshot). Slices are sorted by ID.
type State struct {
	Seq              int               `json:"seq"`
	Orgs             []Org             `json:"orgs"`
	Users            []User            `json:"users"`
	Members          []Member          `json:"members"`
	APIKeys          []APIKey          `json:"api_keys"`
	Invites          []Invite          `json:"invites"`
	Customers        []Customer        `json:"customers"`
	Plans            []Plan            `json:"plans"`
	Subscriptions    []Subscription    `json:"subscriptions"`
	Usage            []UsageRecord     `json:"usage"`
	Invoices         []Invoice         `json:"invoices"`
	Payments         []Payment         `json:"payments"`
	WebhookEndpoints []WebhookEndpoint `json:"webhook_endpoints"`
	Events           []Event           `json:"events"`
	Deliveries       []Delivery        `json:"deliveries"`
}

// Export returns a copy of everything in the store.
func (s *Store) Export() State {
	s.mu.Lock()
	defer s.mu.Unlock()
	st := State{Seq: s.seq}
	for _, o := range s.orgs {
		st.Orgs = append(st.Orgs, o)
	}
	for _, u := range s.users {
		st.Users = append(st.Users, u)
	}
	for _, m := range s.members {
		st.Members = append(st.Members, m)
	}
	for _, k := range s.apiKeys {
		st.APIKeys = append(st.APIKeys, k)
	}
	for _, i := range s.invites {
		st.Invites = append(st.Invites, i)
	}
	for _, c := range s.customers {
		st.Customers = append(st.Customers, copyCustomer(c))
	}
	for _, p := range s.plans {
		st.Plans = append(st.Plans, p)
	}
	for _, sub := range s.subs {
		st.Subscriptions = append(st.Subscriptions, copySub(sub))
	}
	st.Usage = append(st.Usage, s.usage...)
	for _, inv := range s.invoices {
		st.Invoices = append(st.Invoices, copyInvoice(inv))
	}
	for _, p := range s.payments {
		st.Payments = append(st.Payments, p)
	}
	for _, ep := range s.endpoints {
		st.WebhookEndpoints = append(st.WebhookEndpoints, copyEndpoint(ep))
	}
	for _, e := range s.events {
		st.Events = append(st.Events, e)
	}
	for _, d := range s.delivs {
		st.Deliveries = append(st.Deliveries, copyDelivery(d))
	}
	sort.Slice(st.Orgs, func(i, j int) bool { return st.Orgs[i].ID < st.Orgs[j].ID })
	sort.Slice(st.Users, func(i, j int) bool { return st.Users[i].ID < st.Users[j].ID })
	sort.Slice(st.Members, func(i, j int) bool {
		if st.Members[i].OrgID != st.Members[j].OrgID {
			return st.Members[i].OrgID < st.Members[j].OrgID
		}
		return st.Members[i].UserID < st.Members[j].UserID
	})
	sort.Slice(st.APIKeys, func(i, j int) bool { return st.APIKeys[i].ID < st.APIKeys[j].ID })
	sort.Slice(st.Invites, func(i, j int) bool { return st.Invites[i].ID < st.Invites[j].ID })
	sort.Slice(st.Customers, func(i, j int) bool { return st.Customers[i].ID < st.Customers[j].ID })
	sort.Slice(st.Plans, func(i, j int) bool { return st.Plans[i].ID < st.Plans[j].ID })
	sort.Slice(st.Subscriptions, func(i, j int) bool { return st.Subscriptions[i].ID < st.Subscriptions[j].ID })
	sort.Slice(st.Usage, func(i, j int) bool { return st.Usage[i].ID < st.Usage[j].ID })
	sort.Slice(st.Invoices, func(i, j int) bool { return st.Invoices[i].ID < st.Invoices[j].ID })
	sort.Slice(st.Payments, func(i, j int) bool { return st.Payments[i].ID < st.Payments[j].ID })
	sort.Slice(st.WebhookEndpoints, func(i, j int) bool { return st.WebhookEndpoints[i].ID < st.WebhookEndpoints[j].ID })
	sort.Slice(st.Events, func(i, j int) bool { return st.Events[i].ID < st.Events[j].ID })
	sort.Slice(st.Deliveries, func(i, j int) bool { return st.Deliveries[i].ID < st.Deliveries[j].ID })
	return st
}

// FromState builds a store holding st.
func FromState(st State) (*Store, error) {
	s := New()
	s.seq = st.Seq
	dup := func(kind, id string, seen map[string]bool) error {
		if id == "" || seen[id] {
			return fmt.Errorf("%w: %s %q is missing or repeated", ErrInvalid, kind, id)
		}
		seen[id] = true
		return nil
	}
	seen := map[string]bool{}
	for _, o := range st.Orgs {
		if err := dup("organization", o.ID, seen); err != nil {
			return nil, err
		}
		s.orgs[o.ID] = o
	}
	for _, u := range st.Users {
		if err := dup("user", u.ID, seen); err != nil {
			return nil, err
		}
		s.users[u.ID] = u
		s.usersByEmail[normEmail(u.Email)] = u.ID
	}
	for _, m := range st.Members {
		if _, ok := s.orgs[m.OrgID]; !ok {
			return nil, fmt.Errorf("%w: member of unknown organization %q", ErrInvalid, m.OrgID)
		}
		if _, ok := s.users[m.UserID]; !ok {
			return nil, fmt.Errorf("%w: member is unknown user %q", ErrInvalid, m.UserID)
		}
		s.members[memberKey{m.OrgID, m.UserID}] = m
	}
	for _, k := range st.APIKeys {
		if err := dup("API key", k.ID, seen); err != nil {
			return nil, err
		}
		s.apiKeys[k.ID] = k
		if k.Token != "" {
			s.keysByToken[k.Token] = k.ID
		}
	}
	for _, i := range st.Invites {
		if err := dup("invite", i.ID, seen); err != nil {
			return nil, err
		}
		s.invites[i.ID] = i
	}
	for _, c := range st.Customers {
		if err := dup("customer", c.ID, seen); err != nil {
			return nil, err
		}
		s.customers[c.ID] = copyCustomer(c)
		s.customersByEmail[normEmail(c.Email)] = c.ID
	}
	for _, p := range st.Plans {
		if err := dup("plan", p.ID, seen); err != nil {
			return nil, err
		}
		s.plans[p.ID] = p
	}
	for _, sub := range st.Subscriptions {
		if err := dup("subscription", sub.ID, seen); err != nil {
			return nil, err
		}
		s.subs[sub.ID] = copySub(sub)
	}
	s.usage = append(s.usage, st.Usage...)
	for _, inv := range st.Invoices {
		if err := dup("invoice", inv.ID, seen); err != nil {
			return nil, err
		}
		s.invoices[inv.ID] = copyInvoice(inv)
	}
	for _, p := range st.Payments {
		if err := dup("payment", p.ID, seen); err != nil {
			return nil, err
		}
		s.payments[p.ID] = p
	}
	for _, ep := range st.WebhookEndpoints {
		if err := dup("webhook endpoint", ep.ID, seen); err != nil {
			return nil, err
		}
		s.endpoints[ep.ID] = copyEndpoint(ep)
	}
	for _, e := range st.Events {
		if err := dup("event", e.ID, seen); err != nil {
			return nil, err
		}
		s.events[e.ID] = e
	}
	for _, d := range st.Deliveries {
		if err := dup("delivery", d.ID, seen); err != nil {
			return nil, err
		}
		s.delivs[d.ID] = copyDelivery(d)
	}
	return s, nil
}

package store

import (
	"encoding/json"
	"sort"
	"strings"
	"time"
)

// ---- plans

// CreatePlan adds a plan. UsageType defaults to Licensed; a new plan is active.
func (s *Store) CreatePlan(p Plan, now time.Time) (Plan, error) {
	p.Name = strings.TrimSpace(p.Name)
	if p.UsageType == "" {
		p.UsageType = Licensed
	}
	p.Active = true
	if err := checkPlan(p); err != nil {
		return Plan{}, err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.orgs[p.OrgID]; !ok {
		return Plan{}, ErrNotFound
	}
	p.ID = s.newID("plan")
	p.CreatedAt = now.UTC()
	s.plans[p.ID] = p
	return p, nil
}

func checkPlan(p Plan) error {
	switch {
	case p.Name == "":
		return invalid("a plan needs a name")
	case !p.Currency.Valid():
		return invalid("unknown currency %q", p.Currency)
	case p.UnitAmount < 0:
		return invalid("a plan's price cannot be negative")
	case p.Interval != Monthly && p.Interval != Yearly:
		return invalid("a plan bills every month or every year")
	case p.UsageType != Licensed && p.UsageType != Metered:
		return invalid("a plan is licensed or metered")
	case p.TrialDays < 0 || p.TrialDays > 365:
		return invalid("a trial lasts 0 to 365 days")
	}
	return nil
}

// Plan returns one of an organization's plans.
func (s *Store) Plan(orgID, id string) (Plan, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	p, ok := s.plans[id]
	if !ok || p.OrgID != orgID {
		return Plan{}, false
	}
	return p, true
}

// Plans returns an organization's plans, oldest first.
func (s *Store) Plans(orgID string) []Plan {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Plan{}
	for _, p := range s.plans {
		if p.OrgID == orgID {
			out = append(out, p)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// UpdatePlan changes a plan with f. Its currency, price, interval and usage type cannot change once created: subscriptions
// depend on them.
func (s *Store) UpdatePlan(orgID, id string, f func(*Plan) error) (Plan, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	old, ok := s.plans[id]
	if !ok || old.OrgID != orgID {
		return Plan{}, ErrNotFound
	}
	p := old
	if err := f(&p); err != nil {
		return Plan{}, err
	}
	p.ID, p.OrgID, p.CreatedAt = old.ID, old.OrgID, old.CreatedAt
	p.Currency, p.UnitAmount, p.Interval, p.UsageType = old.Currency, old.UnitAmount, old.Interval, old.UsageType
	p.Name = strings.TrimSpace(p.Name)
	if err := checkPlan(p); err != nil {
		return Plan{}, err
	}
	s.plans[id] = p
	return p, nil
}

// ---- subscriptions

// CreateSubscription stores a new subscription. The caller sets its status and periods.
func (s *Store) CreateSubscription(sub Subscription, now time.Time) (Subscription, error) {
	if sub.Quantity <= 0 {
		return Subscription{}, invalid("the quantity must be at least 1")
	}
	if sub.DiscountPercent < 0 || sub.DiscountPercent > 100 {
		return Subscription{}, invalid("the discount is 0 to 100 percent")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.customers[sub.CustomerID]; !ok {
		return Subscription{}, ErrNotFound
	}
	if p, ok := s.plans[sub.PlanID]; !ok || p.OrgID != sub.OrgID {
		return Subscription{}, ErrNotFound
	}
	sub.ID = s.newID("sub")
	sub.CreatedAt = now.UTC()
	s.subs[sub.ID] = sub
	return copySub(sub), nil
}

// Subscription returns one of an organization's subscriptions.
func (s *Store) Subscription(orgID, id string) (Subscription, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	sub, ok := s.subs[id]
	if !ok || sub.OrgID != orgID {
		return Subscription{}, false
	}
	return copySub(sub), true
}

// SubscriptionFilter narrows Subscriptions.
type SubscriptionFilter struct {
	CustomerID string
	Status     SubStatus
}

// Subscriptions returns an organization's subscriptions that match f, oldest first.
func (s *Store) Subscriptions(orgID string, f SubscriptionFilter) []Subscription {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Subscription{}
	for _, sub := range s.subs {
		if sub.OrgID != orgID || (f.CustomerID != "" && sub.CustomerID != f.CustomerID) || (f.Status != "" && sub.Status != f.Status) {
			continue
		}
		out = append(out, copySub(sub))
	}
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// UpdateSubscription changes a subscription with f, which may refuse with an error.
func (s *Store) UpdateSubscription(orgID, id string, f func(*Subscription) error) (Subscription, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	old, ok := s.subs[id]
	if !ok || old.OrgID != orgID {
		return Subscription{}, ErrNotFound
	}
	sub := copySub(old)
	if err := f(&sub); err != nil {
		return Subscription{}, err
	}
	sub.ID, sub.OrgID, sub.CustomerID, sub.CreatedAt = old.ID, old.OrgID, old.CustomerID, old.CreatedAt
	if sub.Quantity <= 0 {
		return Subscription{}, invalid("the quantity must be at least 1")
	}
	if p, ok := s.plans[sub.PlanID]; !ok || p.OrgID != orgID {
		return Subscription{}, ErrNotFound
	}
	s.subs[id] = sub
	return copySub(sub), nil
}

// DueSubscriptions returns the subscriptions of every organization whose current period has ended by now and that are not
// canceled, the longest overdue first.
func (s *Store) DueSubscriptions(now time.Time) []Subscription {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Subscription{}
	for _, sub := range s.subs {
		if sub.Status != Canceled && !sub.CurrentPeriodEnd.After(now) {
			out = append(out, copySub(sub))
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].CurrentPeriodEnd.Equal(out[j].CurrentPeriodEnd) {
			return out[i].CurrentPeriodEnd.Before(out[j].CurrentPeriodEnd)
		}
		return out[i].ID < out[j].ID
	})
	return out
}

func copySub(sub Subscription) Subscription {
	if sub.TrialEnd != nil {
		t := *sub.TrialEnd
		sub.TrialEnd = &t
	}
	if sub.CanceledAt != nil {
		t := *sub.CanceledAt
		sub.CanceledAt = &t
	}
	return sub
}

// AddUsage records usage of a subscription to a metered plan at time at.
func (s *Store) AddUsage(orgID, subID string, quantity int64, at, now time.Time) (UsageRecord, error) {
	if quantity <= 0 {
		return UsageRecord{}, invalid("usage must be a positive quantity")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	sub, ok := s.subs[subID]
	if !ok || sub.OrgID != orgID {
		return UsageRecord{}, ErrNotFound
	}
	if p := s.plans[sub.PlanID]; p.UsageType != Metered {
		return UsageRecord{}, invalid("the subscription's plan is not metered")
	}
	u := UsageRecord{ID: s.newID("use"), OrgID: orgID, SubscriptionID: subID, Quantity: quantity, At: at.UTC(), CreatedAt: now.UTC()}
	s.usage = append(s.usage, u)
	return u, nil
}

// UsageTotal adds up a subscription's usage at times in [from, to).
func (s *Store) UsageTotal(orgID, subID string, from, to time.Time) int64 {
	s.mu.Lock()
	defer s.mu.Unlock()
	var n int64
	for _, u := range s.usage {
		if u.OrgID == orgID && u.SubscriptionID == subID && !u.At.Before(from) && u.At.Before(to) {
			n += u.Quantity
		}
	}
	return n
}

// ---- invoices

// CreateInvoice stores an invoice for one of the organization's customers, with the organization's tax rate. It is open.
func (s *Store) CreateInvoice(inv Invoice, now time.Time) (Invoice, error) {
	if !inv.Currency.Valid() {
		return Invoice{}, invalid("unknown currency %q", inv.Currency)
	}
	if inv.DiscountPercent < 0 || inv.DiscountPercent > 100 {
		return Invoice{}, invalid("the discount is 0 to 100 percent")
	}
	for _, l := range inv.Lines {
		if l.Quantity <= 0 {
			return Invoice{}, invalid("a line needs a positive quantity")
		}
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	org, ok := s.orgs[inv.OrgID]
	if !ok {
		return Invoice{}, ErrNotFound
	}
	c, ok := s.customers[inv.CustomerID]
	if !ok {
		return Invoice{}, ErrNotFound
	}
	if c.OrgID != inv.OrgID {
		return Invoice{}, ErrCustomerOrgMismatch
	}
	inv.ID = s.newID("in")
	inv.TaxRateBP = org.TaxRateBP
	inv.Status = InvoiceOpen
	inv.CreatedAt = now.UTC()
	inv.PaidAt, inv.VoidedAt = nil, nil
	inv = copyInvoice(inv)
	s.invoices[inv.ID] = inv
	return copyInvoice(inv), nil
}

// Invoice returns one of an organization's invoices.
func (s *Store) Invoice(orgID, id string) (Invoice, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	inv, ok := s.invoices[id]
	if !ok || inv.OrgID != orgID {
		return Invoice{}, false
	}
	return copyInvoice(inv), true
}

// InvoiceByID returns an invoice of any organization (background jobs and the admin tool).
func (s *Store) InvoiceByID(id string) (Invoice, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	inv, ok := s.invoices[id]
	return copyInvoice(inv), ok
}

// InvoiceFilter narrows ListInvoices.
type InvoiceFilter struct {
	CustomerID     string
	SubscriptionID string
	Status         InvoiceStatus
}

// ListInvoices returns an organization's invoices that match f, oldest first (ties by ID).
func (s *Store) ListInvoices(orgID string, f InvoiceFilter) []Invoice {
	s.mu.Lock()
	all := make([]Invoice, 0, len(s.invoices))
	for _, inv := range s.invoices {
		all = append(all, inv)
	}
	s.mu.Unlock()
	out := []Invoice{}
	for _, inv := range all {
		c := cloneInvoice(inv)
		if c.OrgID != orgID {
			continue
		}
		if (f.CustomerID != "" && c.CustomerID != f.CustomerID) || (f.SubscriptionID != "" && c.SubscriptionID != f.SubscriptionID) || (f.Status != "" && c.Status != f.Status) {
			continue
		}
		out = append(out, c)
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
			return out[i].CreatedAt.Before(out[j].CreatedAt)
		}
		return out[i].ID < out[j].ID
	})
	return out
}

// UpdateInvoice changes an invoice with f, which may refuse with an error. Only its status, timestamps and lines change.
func (s *Store) UpdateInvoice(orgID, id string, f func(*Invoice) error) (Invoice, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	old, ok := s.invoices[id]
	if !ok || old.OrgID != orgID {
		return Invoice{}, ErrNotFound
	}
	inv := copyInvoice(old)
	if err := f(&inv); err != nil {
		return Invoice{}, err
	}
	inv.ID, inv.OrgID, inv.CustomerID, inv.SubscriptionID, inv.Currency, inv.CreatedAt = old.ID, old.OrgID, old.CustomerID, old.SubscriptionID, old.Currency, old.CreatedAt
	s.invoices[id] = copyInvoice(inv)
	return copyInvoice(inv), nil
}

// copyInvoice is a deep copy, so callers cannot change stored lines.
func copyInvoice(inv Invoice) Invoice {
	inv.Lines = append([]Line(nil), inv.Lines...)
	for _, p := range []**time.Time{&inv.PeriodStart, &inv.PeriodEnd, &inv.PaidAt, &inv.VoidedAt} {
		if *p != nil {
			t := **p
			*p = &t
		}
	}
	return inv
}

// cloneInvoice is a deep copy through JSON, which cannot miss a field added later.
func cloneInvoice(inv Invoice) Invoice {
	b, err := json.Marshal(inv)
	if err != nil {
		return copyInvoice(inv)
	}
	var out Invoice
	if err := json.Unmarshal(b, &out); err != nil {
		return copyInvoice(inv)
	}
	return out
}

// ---- payments

// CreatePayment records a payment attempt for one of the organization's invoices.
func (s *Store) CreatePayment(p Payment, now time.Time) (Payment, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	inv, ok := s.invoices[p.InvoiceID]
	if !ok || inv.OrgID != p.OrgID {
		return Payment{}, ErrNotFound
	}
	if p.Status != PaymentSucceeded && p.Status != PaymentFailed {
		return Payment{}, invalid("a payment succeeded or failed")
	}
	p.ID = s.newID("pay")
	p.CreatedAt = now.UTC()
	s.payments[p.ID] = p
	return p, nil
}

// Payments returns an organization's payments, oldest first, only those of one invoice when invoiceID is set.
func (s *Store) Payments(orgID, invoiceID string) []Payment {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := []Payment{}
	for _, p := range s.payments {
		if p.OrgID == orgID && (invoiceID == "" || p.InvoiceID == invoiceID) {
			out = append(out, p)
		}
	}
	sort.Slice(out, func(i, j int) bool {
		if !out[i].CreatedAt.Equal(out[j].CreatedAt) {
			return out[i].CreatedAt.Before(out[j].CreatedAt)
		}
		return out[i].ID < out[j].ID
	})
	return out
}
package store

import (
	"fmt"
	"sort"
)

// State is everything a store holds, for snapshots (package snapshot). Slices are sorted by ID.
type State struct {
	Seq              int               `json:"seq"`
	Orgs             []Org             `json:"orgs"`
	Users            []User            `json:"users"`
	Members          []Member          `json:"members"`
	APIKeys          []APIKey          `json:"api_keys"`
	Invites          []Invite          `json:"invites"`
	Customers        []Customer        `json:"customers"`
	Plans            []Plan            `json:"plans"`
	Subscriptions    []Subscription    `json:"subscriptions"`
	Usage            []UsageRecord     `json:"usage"`
	Invoices         []Invoice         `json:"invoices"`
	Payments         []Payment         `json:"payments"`
	WebhookEndpoints []WebhookEndpoint `json:"webhook_endpoints"`
	Events           []Event           `json:"events"`
	Deliveries       []Delivery        `json:"deliveries"`
}

// Export returns a copy of everything in the store.
func (s *Store) Export() State {
	s.mu.Lock()
	defer s.mu.Unlock()
	st := State{Seq: s.seq}
	for _, o := range s.orgs {
		st.Orgs = append(st.Orgs, o)
	}
	for _, u := range s.users {
		st.Users = append(st.Users, u)
	}
	for _, m := range s.members {
		st.Members = append(st.Members, m)
	}
	for _, k := range s.apiKeys {
		st.APIKeys = append(st.APIKeys, k)
	}
	for _, i := range s.invites {
		st.Invites = append(st.Invites, i)
	}
	for _, c := range s.customers {
		st.Customers = append(st.Customers, copyCustomer(c))
	}
	for _, p := range s.plans {
		st.Plans = append(st.Plans, p)
	}
	for _, sub := range s.subs {
		st.Subscriptions = append(st.Subscriptions, copySub(sub))
	}
	st.Usage = append(st.Usage, s.usage...)
	for _, inv := range s.invoices {
		st.Invoices = append(st.Invoices, copyInvoice(inv))
	}
	for _, p := range s.payments {
		st.Payments = append(st.Payments, p)
	}
	for _, ep := range s.endpoints {
		st.WebhookEndpoints = append(st.WebhookEndpoints, copyEndpoint(ep))
	}
	for _, e := range s.events {
		st.Events = append(st.Events, e)
	}
	for _, d := range s.delivs {
		st.Deliveries = append(st.Deliveries, copyDelivery(d))
	}
	sort.Slice(st.Orgs, func(i, j int) bool { return st.Orgs[i].ID < st.Orgs[j].ID })
	sort.Slice(st.Users, func(i, j int) bool { return st.Users[i].ID < st.Users[j].ID })
	sort.Slice(st.Members, func(i, j int) bool {
		if st.Members[i].OrgID != st.Members[j].OrgID {
			return st.Members[i].OrgID < st.Members[j].OrgID
		}
		return st.Members[i].UserID < st.Members[j].UserID
	})
	sort.Slice(st.APIKeys, func(i, j int) bool { return st.APIKeys[i].ID < st.APIKeys[j].ID })
	sort.Slice(st.Invites, func(i, j int) bool { return st.Invites[i].ID < st.Invites[j].ID })
	sort.Slice(st.Customers, func(i, j int) bool { return st.Customers[i].ID < st.Customers[j].ID })
	sort.Slice(st.Plans, func(i, j int) bool { return st.Plans[i].ID < st.Plans[j].ID })
	sort.Slice(st.Subscriptions, func(i, j int) bool { return st.Subscriptions[i].ID < st.Subscriptions[j].ID })
	sort.Slice(st.Usage, func(i, j int) bool { return st.Usage[i].ID < st.Usage[j].ID })
	sort.Slice(st.Invoices, func(i, j int) bool { return st.Invoices[i].ID < st.Invoices[j].ID })
	sort.Slice(st.Payments, func(i, j int) bool { return st.Payments[i].ID < st.Payments[j].ID })
	sort.Slice(st.WebhookEndpoints, func(i, j int) bool { return st.WebhookEndpoints[i].ID < st.WebhookEndpoints[j].ID })
	sort.Slice(st.Events, func(i, j int) bool { return st.Events[i].ID < st.Events[j].ID })
	sort.Slice(st.Deliveries, func(i, j int) bool { return st.Deliveries[i].ID < st.Deliveries[j].ID })
	return st
}

// FromState builds a store holding st.
func FromState(st State) (*Store, error) {
	s := New()
	s.seq = st.Seq
	dup := func(kind, id string, seen map[string]bool) error {
		if id == "" || seen[id] {
			return fmt.Errorf("%w: %s %q is missing or repeated", ErrInvalid, kind, id)
		}
		seen[id] = true
		return nil
	}
	seen := map[string]bool{}
	for _, o := range st.Orgs {
		if err := dup("organization", o.ID, seen); err != nil {
			return nil, err
		}
		s.orgs[o.ID] = o
	}
	for _, u := range st.Users {
		if err := dup("user", u.ID, seen); err != nil {
			return nil, err
		}
		s.users[u.ID] = u
		s.usersByEmail[normEmail(u.Email)] = u.ID
	}
	for _, m := range st.Members {
		if _, ok := s.orgs[m.OrgID]; !ok {
			return nil, fmt.Errorf("%w: member of unknown organization %q", ErrInvalid, m.OrgID)
		}
		if _, ok := s.users[m.UserID]; !ok {
			return nil, fmt.Errorf("%w: member is unknown user %q", ErrInvalid, m.UserID)
		}
		s.members[memberKey{m.OrgID, m.UserID}] = m
	}
	for _, k := range st.APIKeys {
		if err := dup("API key", k.ID, seen); err != nil {
			return nil, err
		}
		s.apiKeys[k.ID] = k
		if k.Token != "" {
			s.keysByToken[k.Token] = k.ID
		}
	}
	for _, i := range st.Invites {
		if err := dup("invite", i.ID, seen); err != nil {
			return nil, err
		}
		s.invites[i.ID] = i
	}
	for _, c := range st.Customers {
		if err := dup("customer", c.ID, seen); err != nil {
			return nil, err
		}
		s.customers[c.ID] = copyCustomer(c)
		s.customersByEmail[normEmail(c.Email)] = c.ID
	}
	for _, p := range st.Plans {
		if err := dup("plan", p.ID, seen); err != nil {
			return nil, err
		}
		s.plans[p.ID] = p
	}
	for _, sub := range st.Subscriptions {
		if err := dup("subscription", sub.ID, seen); err != nil {
			return nil, err
		}
		s.subs[sub.ID] = copySub(sub)
	}
	s.usage = append(s.usage, st.Usage...)
	for _, inv := range st.Invoices {
		if err := dup("invoice", inv.ID, seen); err != nil {
			return nil, err
		}
		s.invoices[inv.ID] = copyInvoice(inv)
	}
	for _, p := range st.Payments {
		if err := dup("payment", p.ID, seen); err != nil {
			return nil, err
		}
		s.payments[p.ID] = p
	}
	for _, ep := range st.WebhookEndpoints {
		if err := dup("webhook endpoint", ep.ID, seen); err != nil {
			return nil, err
		}
		s.endpoints[ep.ID] = copyEndpoint(ep)
	}
	for _, e := range st.Events {
		if err := dup("event", e.ID, seen); err != nil {
			return nil, err
		}
		s.events[e.ID] = e
	}
	for _, d := range st.Deliveries {
		if err := dup("delivery", d.ID, seen); err != nil {
			return nil, err
		}
		s.delivs[d.ID] = copyDelivery(d)
	}
	return s, nil
}

// Package store keeps Tally's data in memory. It is safe for concurrent use.
//
// Every object belongs to one organization. Methods that take an orgID only ever see that organization's objects; the few
// methods that find an object by ID alone (CustomerByID, InvoiceByID, EventByID) are for background jobs and the admin
// tool, which act on behalf of the system rather than a member.
package store

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"sort"
	"strings"
	"sync"
	"time"
)

// Errors. Callers check them with errors.Is; most are wrapped with a detail.
var (
	ErrNotFound      = errors.New("not found")
	ErrInvalid       = errors.New("invalid")
	ErrConflict      = errors.New("conflict")
	ErrEmailTaken    = fmt.Errorf("%w: email address already in use", ErrConflict)
	ErrAlreadyMember = fmt.Errorf("%w: already a member", ErrConflict)
	// ErrCustomerOrgMismatch is returned when an object names a customer of another organization.
	ErrCustomerOrgMismatch = errors.New("customer belongs to another organization")
)

// Store holds everything.
type Store struct {
	mu  sync.Mutex
	seq int

	orgs         map[string]Org
	users        map[string]User
	usersByEmail map[string]string // lower-case email -> user ID
	members      map[memberKey]Member
	apiKeys      map[string]APIKey
	keysByToken  map[string]string // token -> key ID
	invites      map[string]Invite

	customers        map[string]Customer
	customersByEmail map[string]string // lower-case email -> customer ID

	plans     map[string]Plan
	subs      map[string]Subscription
	usage     []UsageRecord
	invoices  map[string]Invoice
	payments  map[string]Payment
	endpoints map[string]WebhookEndpoint
	events    map[string]Event
	delivs    map[string]Delivery
}

type memberKey struct{ org, user string }

// New returns an empty store.
func New() *Store {
	return &Store{
		orgs: map[string]Org{}, users: map[string]User{}, usersByEmail: map[string]string{}, members: map[memberKey]Member{},
		apiKeys: map[string]APIKey{}, keysByToken: map[string]string{}, invites: map[string]Invite{},
		customers: map[string]Customer{}, customersByEmail: map[string]string{},
		plans: map[string]Plan{}, subs: map[string]Subscription{}, invoices: map[string]Invoice{}, payments: map[string]Payment{},
		endpoints: map[string]WebhookEndpoint{}, events: map[string]Event{}, delivs: map[string]Delivery{},
	}
}

// newID returns the next ID with the prefix, for example "cus_000042". The caller holds the lock.
func (s *Store) newID(prefix string) string {
	s.seq++
	return fmt.Sprintf("%s_%06d", prefix, s.seq)
}

// NewToken returns prefix followed by 32 random hex characters.
func NewToken(prefix string) string {
	b := make([]byte, 16)
	if _, err := rand.Read(b); err != nil {
		panic(err) // crypto/rand does not fail on supported platforms
	}
	return prefix + hex.EncodeToString(b)
}

func normEmail(email string) string { return strings.ToLower(strings.TrimSpace(email)) }

func validEmail(email string) bool {
	at := strings.Index(email, "@")
	return at > 0 && at < len(email)-1 && !strings.ContainsAny(email, " \t\r\n,;<>")
}

func invalid(format string, args ...any) error {
	return fmt.Errorf("%w: %s", ErrInvalid, fmt.Sprintf(format, args...))
}

// ---- organizations

// CreateOrg adds an organization.
func (s *Store) CreateOrg(name string, plan OrgPlan, timeZone string, taxRateBP int, now time.Time) (Org, error) {
	o := Org{Name: strings.TrimSpace(name), Plan: plan, TimeZone: timeZone, TaxRateBP: taxRateBP, CreatedAt: now.UTC()}
	if err := checkOrg(o); err != nil {
		return Org{}, err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	o.ID = s.newID("org")
	s.orgs[o.ID] = o
	return o, nil
}

func checkOrg(o Org) error {
	if o.Name == "" {
		return invalid("an organization needs a name")
	}
	if !o.Plan.Valid() {
		return invalid("unknown plan %q", o.Plan)
	}
	if _, err := time.LoadLocation(o.TimeZone); err != nil || o.TimeZone == "" {
		return invalid("unknown time zone %q", o.TimeZone)
	}
	if o.TaxRateBP < 0 || o.TaxRateBP > 10000 {
		return invalid("the tax rate is 0 to 10000 basis points")
	}
	return nil
}

// Org returns an organization.
func (s *Store) Org(id string) (Org, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	o, ok := s.orgs[id]
	return o, ok
}

// UpdateOrg changes an organization with f, which may refuse with an error.
func (s *Store) UpdateOrg(id string, f func(*Org) error) (Org, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	o, ok := s.orgs[id]
	if !ok {
		return Org{}, ErrNotFound
	}
	if err := f(&o); err != nil {
		return Org{}, err
	}
	o.ID = id
	if err := checkOrg(o); err != nil {
		return Org{}, err
	}
	s.orgs[id] = o
	return o, nil
// Package subscriptions runs subscriptions: starting them with their first invoice, changing and canceling them, and
// renewing them when a billing period ends.
package subscriptions

import (
	"context"
	"errors"
	"fmt"
	"time"

	"example.com/tally/internal/billing"
	"example.com/tally/internal/clock"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/store"
)

// Errors.
var (
	ErrPlanInactive = errors.New("the plan is not active")
	ErrCanceled     = errors.New("the subscription is canceled")
)

// Service runs subscriptions.
type Service struct {
	Store     *store.Store
	Payments  *payments.Service
	Clock     clock.Clock
	Publisher payments.Publisher // nil: no events
}

// CreateInput is a new subscription.
type CreateInput struct {
	CustomerID      string
	PlanID          string
	Quantity        int // 0 means 1
	DiscountPercent int
}

// Create starts a subscription now. With a plan that has a trial, the subscription is trialing until the trial ends, and
// its first period starts then. Otherwise its first period starts now; for a licensed plan that period is invoiced at once
// and charged to the customer's default payment method, if it has one (a declined charge makes the subscription past due).
func (s *Service) Create(ctx context.Context, orgID string, in CreateInput) (store.Subscription, error) {
	plan, ok := s.Store.Plan(orgID, in.PlanID)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	if !plan.Active {
		return store.Subscription{}, ErrPlanInactive
	}
	if in.Quantity == 0 {
		in.Quantity = 1
	}
	now := s.Clock.Now()
	sub := store.Subscription{OrgID: orgID, CustomerID: in.CustomerID, PlanID: plan.ID, Quantity: in.Quantity, DiscountPercent: in.DiscountPercent,
		StartedAt: now, CurrentPeriodStart: now}
	if plan.TrialDays > 0 {
		end := now.AddDate(0, 0, plan.TrialDays)
		sub.Status, sub.TrialEnd, sub.CurrentPeriodEnd = store.Trialing, &end, end
	} else {
		sub.Status, sub.CurrentPeriodEnd = store.Active, billing.AddInterval(now, plan.Interval)
	}
	sub, err := s.Store.CreateSubscription(sub, now)
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.created", sub)
	if sub.Status == store.Active && plan.UsageType == store.Licensed {
		paid, err := s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
		if err != nil {
			return sub, err
		}
		if !paid {
			if sub, err = s.setStatus(ctx, sub, store.PastDue); err != nil {
				return sub, err
			}
		}
	}
	return sub, nil
}

// UpdateInput changes a subscription; nil fields stay as they are.
type UpdateInput struct {
	PlanID   *string
	Quantity *int
}

// Update changes a subscription's plan or quantity. The change applies at once and is billed from the next period on.
func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
	if in.PlanID != nil {
		p, ok := s.Store.Plan(orgID, *in.PlanID)
		if !ok {
			return store.Subscription{}, store.ErrNotFound
		}
		if !p.Active {
			return store.Subscription{}, ErrPlanInactive
		}
	}
	sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
		if sub.Status == store.Canceled {
			return ErrCanceled
		}
		if in.PlanID != nil {
			sub.PlanID = *in.PlanID
		}
		if in.Quantity != nil {
			sub.Quantity = *in.Quantity
		}
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.updated", sub)
	return sub, nil
}

// Cancel cancels a subscription now, or at the end of its current period when atPeriodEnd is set. Canceling a canceled
// subscription changes nothing.
func (s *Service) Cancel(ctx context.Context, orgID, id string, atPeriodEnd bool) (store.Subscription, error) {
	now := s.Clock.Now()
	sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
		if sub.Status == store.Canceled {
			return nil
		}
		if atPeriodEnd {
			sub.CancelAtPeriodEnd = true
			return nil
		}
		sub.Status, sub.CanceledAt = store.Canceled, &now
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
	if sub.Status == store.Canceled {
		s.publish(ctx, orgID, "subscription.canceled", sub)
	} else {
		s.publish(ctx, orgID, "subscription.updated", sub)
	}
	return sub, nil
}

// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
// due. RenewDue returns how many subscriptions it renewed or canceled.
func (s *Service) RenewDue(ctx context.Context) (int, error) {
	now := s.Clock.Now()
	n := 0
	for _, sub := range s.Store.DueSubscriptions(now) {
		if err := ctx.Err(); err != nil {
			return n, err
		}
		if err := s.renew(ctx, sub, now); err != nil {
			return n, fmt.Errorf("renew %s: %w", sub.ID, err)
		}
		n++
	}
	return n, nil
}

func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
	plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
	if !ok {
		return store.ErrNotFound
	}
	if sub.CancelAtPeriodEnd {
		end := sub.CurrentPeriodEnd
		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
			x.Status, x.CanceledAt = store.Canceled, &end
			return nil
		})
		if err == nil {
			s.publish(ctx, sub.OrgID, "subscription.canceled", sub)
		}
		return err
	}
	start := now
	end := billing.AddInterval(start, plan.Interval)
	paid := true
	var err error
	switch {
	case plan.UsageType == store.Metered && sub.Status != store.Trialing:
		paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
	case plan.UsageType == store.Licensed:
		paid, err = s.invoicePeriod(ctx, sub, plan, start, end)
	}
	if err != nil {
		return err
	}
	sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
		x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
		if paid {
			x.Status = store.Active
		} else {
			x.Status = store.PastDue
		}
		return nil
	})
	if err != nil {
		return err
	}
	s.publish(ctx, sub.OrgID, "subscription.updated", sub)
	return nil
}

// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
// payment method stays open and counts as paid here (it is paid by hand).
func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
	var lines []store.Line
	period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
	switch plan.UsageType {
	case store.Licensed:
		if plan.UnitAmount > 0 {
			lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
		}
	case store.Metered:
		if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
			lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
		}
	}
	ps, pe := start, end
	inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
		Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
	if err != nil {
		return false, err
	}
	s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
	_, _, err = s.Payments.Pay(ctx, sub.OrgID, inv.ID, "")
	var decline *payments.DeclineError
	switch {
	case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
		return true, nil
	case errors.As(err, &decline):
		return false, nil
	default:
		return false, err
	}
}

func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
	sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
		x.Status = st
		return nil
	})
	if err == nil {
		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
	}
	return sub, err
}

func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
	if s.Publisher != nil {
		_ = s.Publisher.Publish(ctx, orgID, typ, data)
	}
}

// Package store keeps Tally's data in memory. It is safe for concurrent use.
//
// Every object belongs to one organization. Methods that take an orgID only ever see that organization's objects; the few
// methods that find an object by ID alone (CustomerByID, InvoiceByID, EventByID) are for background jobs and the admin
// tool, which act on behalf of the system rather than a member.
package store

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"sort"
	"strings"
	"sync"
	"time"
)

// Errors. Callers check them with errors.Is; most are wrapped with a detail.
var (
	ErrNotFound      = errors.New("not found")
	ErrInvalid       = errors.New("invalid")
	ErrConflict      = errors.New("conflict")
	ErrEmailTaken    = fmt.Errorf("%w: email address already in use", ErrConflict)
	ErrAlreadyMember = fmt.Errorf("%w: already a member", ErrConflict)
	// ErrCustomerOrgMismatch is returned when an object names a customer of another organization.
	ErrCustomerOrgMismatch = errors.New("customer belongs to another organization")
)

// Store holds everything.
type Store struct {
	mu  sync.Mutex
	seq int

	orgs         map[string]Org
	users        map[string]User
	usersByEmail map[string]string // lower-case email -> user ID
	members      map[memberKey]Member
	apiKeys      map[string]APIKey
	keysByToken  map[string]string // token -> key ID
	invites      map[string]Invite

	customers        map[string]Customer
	customersByEmail map[string]string // lower-case email -> customer ID

	plans     map[string]Plan
	subs      map[string]Subscription
	usage     []UsageRecord
	invoices  map[string]Invoice
	payments  map[string]Payment
	endpoints map[string]WebhookEndpoint
	events    map[string]Event
	delivs    map[string]Delivery
}

type memberKey struct{ org, user string }

// New returns an empty store.
func New() *Store {
	return &Store{
		orgs: map[string]Org{}, users: map[string]User{}, usersByEmail: map[string]string{}, members: map[memberKey]Member{},
		apiKeys: map[string]APIKey{}, keysByToken: map[string]string{}, invites: map[string]Invite{},
		customers: map[string]Customer{}, customersByEmail: map[string]string{},
		plans: map[string]Plan{}, subs: map[string]Subscription{}, invoices: map[string]Invoice{}, payments: map[string]Payment{},
		endpoints: map[string]WebhookEndpoint{}, events: map[string]Event{}, delivs: map[string]Delivery{},
	}
}

// newID returns the next ID with the prefix, for example "cus_000042". The caller holds the lock.
func (s *Store) newID(prefix string) string {
	s.seq++
	return fmt.Sprintf("%s_%06d", prefix, s.seq)
}

// NewToken returns prefix followed by 32 random hex characters.
func NewToken(prefix string) string {
	b := make([]byte, 16)
	if _, err := rand.Read(b); err != nil {
		panic(err) // crypto/rand does not fail on supported platforms
	}
	return prefix + hex.EncodeToString(b)
}

func normEmail(email string) string { return strings.ToLower(strings.TrimSpace(email)) }

func validEmail(email string) bool {
	at := strings.Index(email, "@")
	return at > 0 && at < len(email)-1 && !strings.ContainsAny(email, " \t\r\n,;<>")
}

func invalid(format string, args ...any) error {
	return fmt.Errorf("%w: %s", ErrInvalid, fmt.Sprintf(format, args...))
}

// ---- organizations

// CreateOrg adds an organization.
func (s *Store) CreateOrg(name string, plan OrgPlan, timeZone string, taxRateBP int, now time.Time) (Org, error) {
	o := Org{Name: strings.TrimSpace(name), Plan: plan, TimeZone: timeZone, TaxRateBP: taxRateBP, CreatedAt: now.UTC()}
	if err := checkOrg(o); err != nil {
		return Org{}, err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	o.ID = s.newID("org")
	s.orgs[o.ID] = o
	return o, nil
}

func checkOrg(o Org) error {
	if o.Name == "" {
		return invalid("an organization needs a name")
	}
	if !o.Plan.Valid() {
		return invalid("unknown plan %q", o.Plan)
	}
	if _, err := time.LoadLocation(o.TimeZone); err != nil || o.TimeZone == "" {
		return invalid("unknown time zone %q", o.TimeZone)
	}
	if o.TaxRateBP < 0 || o.TaxRateBP > 10000 {
		return invalid("the tax rate is 0 to 10000 basis points")
	}
	return nil
}

// Org returns an organization.
func (s *Store) Org(id string) (Org, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	o, ok := s.orgs[id]
	return o, ok
}

// UpdateOrg changes an organization with f, which may refuse with an error.
func (s *Store) UpdateOrg(id string, f func(*Org) error) (Org, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	o, ok := s.orgs[id]
	if !ok {
		return Org{}, ErrNotFound
	}
	if err := f(&o); err != nil {
		return Org{}, err
	}
	o.ID = id
	if err := checkOrg(o); err != nil {
		return Org{}, err
	}
	s.orgs[id] = o
	return o, nil
